{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Bicuculline, a phthalideisoquinoline alkaloid sharing the N-methyl-tetrahydroisoquinoline, methylenedioxy, and lactone features of the query, penetrated rat brain in a dose-dependent manner after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Isocorydine, a related aporphine alkaloid with an N-methyl group and multiple methoxy substituents, was detected in rat brain within 10 minutes of administration, demonstrating effective BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Stepholidine, a related tetrahydroprotoberberine alkaloid, showed good brain penetration in rats with a brain-to-plasma AUC ratio of about 0.7 measured by microdialysis.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tylocrebrine, a related polycyclic alkaloid with multiple methoxy groups, accumulated rapidly in mouse brain with an AUCbrain of 2.1 µg·h/mL after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer direct CNS-penetration evidence from structurally related alkaloids, especially bicuculline, strongly supports meaningful BBB access for the query. The physicochemical prior is also favorable, and the poor-penetration records have very low transfer scores and belong to structurally divergent chemotypes.",
  "evidence_gaps": [
    "No direct noscapine-specific brain or CSF pharmacokinetic measurement is included in the provided records.",
    "Efflux transporter involvement for the query is not directly measured, though the high neutral fraction and strong analogue evidence mitigate this uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

